function validate([zero, one, limit]) {
  for (const [name, v] of [['zero', zero], ['one', one], ['limit', limit]]) {
    if (!Number.isInteger(v) || v < 1 || v > 1000) return `${name} must be an integer from 1 to 1000.`;
