function numberOfStableArrays(zero, one, limit) {
  // Build every arrangement bit by bit and check the longest run at the end.
  const n = zero + one;
  let total = 0;
  const arr = [];
  const build = (zerosLeft, onesLeft) => {
    if (arr.length === n) {
      let run = 1, longest = 1;
      for (let k = 1; k < n; k++) {
        run = arr[k] === arr[k - 1] ? run + 1 : 1;
        longest = Math.max(longest, run);
      }
      if (longest <= limit) total++;
      return;
    }
    if (zerosLeft > 0) { arr.push(0); build(zerosLeft - 1, onesLeft); arr.pop(); }
    if (onesLeft > 0) { arr.push(1); build(zerosLeft, onesLeft - 1); arr.pop(); }
  };
  build(zero, one);
  return total % 1000000007;
}

